+it("validates request headers", async () => {
+  const res = await request(app).get("/things");
+  expect(res.status).toBe(400);
+  expect(res.body.error).toBe("missing_api_version");
+  expect((await request(app).get("/things").set("Api-Version", "2")).status).toBe(200);
+});
